INSERT INTO `categories` VALUES (1,'Home and Kitchen','Home & Kitchen includes everyday household and kitchen essentials designed for comfort, convenience, and efficient daily use.','home-and-kitchen','/uploads/categories/1767598216466-144998875.jpg',1,'2026-01-05 07:30:16','2026-02-26 08:16:33','2026-02-26 08:16:33'),(2,'Industrial products','Industrial related products include tools, materials, and accessories designed for durability, safety, and reliable performance in industrial, commercial, and construction environments.','industrial-products','/uploads/categories/1767599915244-165940275.jpg',1,'2026-01-05 07:58:35','2026-01-09 05:56:44','2026-01-09 05:56:44'),(3,'Pooja Supplies & Flags','Pooja Items include essential religious and spiritual products used for daily worship, rituals, and traditional ceremonies at home or temples.\r\n\r\n','pooja-supplies-and-flags','/uploads/categories/1767599988144-564251737.webp',1,'2026-01-05 07:59:48','2026-01-09 06:12:43',NULL),(4,'Health & personal Care','Health & Personal Care includes products designed for daily hygiene, grooming, wellness, and personal well-being.','health-and-personal-care','/uploads/categories/1767600102647-617697793.jpg',1,'2026-01-05 08:01:17','2026-01-14 09:44:11','2026-01-14 09:44:11'),(5,'Snake Item & Garden Tool','Garden Items include tools, accessories, and supplies designed for planting, maintenance, and care of gardens and outdoor spaces.','snake-item-and-garden-tool','/uploads/categories/1767600346651-104285302.jpg',1,'2026-01-05 08:05:46','2026-02-26 08:09:44','2026-02-26 08:09:44'),(6,'Office Products','.','office-products',NULL,1,'2026-01-07 09:17:29','2026-01-09 06:12:48','2026-01-09 06:12:48'),(7,'Industrial & Construction Supplies','High-performance construction product suitable for professional and commercial use. Built to withstand heavy duty work while providing consistent and efficient results.','industrial-and-construction-supplies','/uploads/categories/1767855481984-220878901.jpg