INSERT INTO `faqs` VALUES (1,'Why choose waltzify?','<p>Our<strong> “Customer First Policy”</strong> ensures that all queries are handled seamlessly, providing customers with the best services and products. When it comes to refunds, we never hesitate, ensuring a hassle-free process. Our reliability is well-proven across various online platforms, where we’ve been delivering for the last<strong> 15 years.</strong></p><p>&nbsp;</p><p>Our website offers lower prices compared to other e-commerce platforms like Amazon and Flipkart. By shopping directly with us, you not only save more, but also enjoy the convenience of having a single, direct point of contact.</p><p>&nbsp;</p><p>Whether you reach out via call, WhatsApp, or email, our team is always ready to assist. Choose Waltzify for an experience that’s affordable, reliable, and hassle-free!</p>',1,'2026-01-07 10:16:26','2026-01-07 10:16:26'),(2,'Can we visit your store?','<p>Yes! We welcome you to visit our physical store located in Indore, Madhya Pradesh. Our team will be happy to assist you in person with your product needs. You can find us at:</p><p>&nbsp;</p><p>Waltzer India</p><p>Main Gate, 1A-Balaji Market, Hawa Bangala Rd,</p><p>Near R.R. Cat, Opp. Hari Dham Mandir,</p><p>Indore, Madhya Pradesh 452009.</p><p>&nbsp;</p><p>For any queries, feel free to contact us at:</p><p>Phone: 07314245858, 9522582422</p><p>Email: sales@waltzerindia.com</p>',1,'2026-01-07 10:16:51','2026-01-07 10:16:51'),(3,'Is international shipping available?','<p>Yes! We offer international shipping to many countries. For international orders, feel free to contact us directly at 07314245858, 9522582422, or email us at sales@waltzerindia.com for more details.</p>',1,'2026-01-07 10:17:04','2026-01-07 10:17:04'),(4,'Can I place customized, bulk, or business orders?','<p>Absolutely! We accept bulk and business orders, and offer special discounts specifically for these types of purchases. If you’re looking to buy in larger quantities, you’ll not only get a great price but also benefit from our dedicated service.</p><p>For customized orders, we are happy to offer personalized options to meet all your specific requirements. Just reach out to our customer support team, and we’ll provide tailored solutions to ensure your needs are fully met.</p>',1,'2026-01-07 10:17:16','2026-01-07 10:17:28'),(5,'One contact point!','<p>To make your shopping experience smoother, we provide a single point of contact for all your inquiries. Whether you need help with orders, products, or support, you can easily reach us through:</p><p>&nbsp;</p><p>Phone: 07314245858, 9522582422</p><p>WhatsApp: Use the same numbers for quick communication.</p><p>Email: sales@waltzerindia.com</p><p>Our team is always ready to assist you, ensuring a hassle-free experience from start to finish.</p>',1,'2026-01-07 10:17:44','2026-01-07 10:17:44');
/*!40000 ALTER TABLE `faqs` ENABLE KEYS */;
UNLOCK TABLES;

