DROP TABLE IF EXISTS `orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `orders` (
  `order_id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `address_id` int NOT NULL,
  `shipping_name` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `shipping_phone` varchar(20) COLLATE utf8mb4_general_ci NOT NULL,
  `shipping_email` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `shipping_street` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `shipping_city` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `shipping_state` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `shipping_zip` varchar(20) COLLATE utf8mb4_general_ci NOT NULL,
  `shipping_country` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `gst_number` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `total_amount` decimal(10,2) NOT NULL,
  `total_discount_amount` decimal(10,2) DEFAULT '0.00',
  `total_shipping_price` decimal(10,2) NOT NULL DEFAULT '0.00',
  `extra_delivery_charge` decimal(10,2) DEFAULT '0.00',
  `extra_delivery_charge_type` enum('fixed','percentage') COLLATE utf8mb4_general_ci DEFAULT NULL,
  `extra_delivery_charge_rate` decimal(10,2) DEFAULT '0.00',
  `order_status` enum('PENDING','CONFIRMED','SHIPPED','DELIVERED','CANCELLED','PARTIALLY_CANCELLED','RETURNED','PARTIALLY_RETURNED','RETURN_REQUESTED','REFUNDED','PARTIALLY_REFUNDED') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'PENDING',
  `order_notification_sent` tinyint(1) NOT NULL DEFAULT '0',
  `admin_notification_sent` tinyint(1) NOT NULL DEFAULT '0',
  `order_coupon_id` int DEFAULT NULL,
  `order_coupon_code` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `courier_name` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `courier_tracking_id` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `date_of_shipment` datetime DEFAULT NULL,
  `cod_charge` decimal(10,2) DEFAULT '0.00',
  `cod_charge_type` enum('FLAT','PERCENTAGE') COLLATE utf8mb4_general_ci DEFAULT NULL,
  `cod_charge_rate` decimal(10,2) DEFAULT '0.00',
  `additional_charge` decimal(10,2) DEFAULT '0.00',
  `additional_charge_type` enum('FLAT','PERCENTAGE') COLLATE utf8mb4_general_ci DEFAULT NULL,
  `additional_charge_rate` decimal(10,2) DEFAULT '0.00',
  `invoice_number` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `invoice_date` datetime DEFAULT NULL,
  PRIMARY KEY (`order_id`),
  KEY `idx_user` (`user_id`),
  KEY `idx_address` (`address_id`),
  KEY `idx_status` (`order_status`),
  KEY `idx_created` (`created_at`),
  KEY `idx_user_status` (`user_id`,`order_status`),
  KEY `idx_date_status` (`created_at`,`order_status`),
  KEY `idx_orders_notification` (`order_id`,`order_notification_sent`),
  KEY `idx_orders_admin_notification` (`admin_notification_sent`,`order_status`),
  KEY `idx_orders_admin_notification_sent` (`admin_notification_sent`),
  KEY `idx_orders_shipping_email` (`shipping_email`),
  CONSTRAINT `fk_order_address` FOREIGN KEY (`address_id`) REFERENCES `user_addresses` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_order_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=108 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
