--
-- Table structure for table `payments`
--

DROP TABLE IF EXISTS `payments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `payments` (
  `payment_id` int NOT NULL AUTO_INCREMENT,
  `order_id` int NOT NULL,
  `transaction_id` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `merchant_order_id` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `merchant_user_id` varchar(50) COLLATE utf8mb4_general_ci NOT NULL,
  `payment_method` enum('COD','ONLINE') COLLATE utf8mb4_general_ci NOT NULL,
  `payment_gateway` enum('COD','PhonePe','Razorpay') COLLATE utf8mb4_general_ci NOT NULL,
  `amount` decimal(10,2) NOT NULL,
  `refunded_total` decimal(10,2) DEFAULT '0.00',
  `status` enum('PENDING','SUCCESS','FAILED','REFUNDED','PARTIALLY_REFUNDED') COLLATE utf8mb4_general_ci DEFAULT 'PENDING',
  `payment_reference` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `payment_response` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`payment_id`),
  UNIQUE KEY `order_id` (`order_id`),
  KEY `idx_payment_order` (`order_id`),
  KEY `idx_payment_status` (`status`),
  CONSTRAINT `fk_payment_order` FOREIGN KEY (`order_id`) REFERENCES `orders` (`order_id`) ON DELETE CASCADE,
  CONSTRAINT `payments_chk_1` CHECK (json_valid(`payment_response`))
) ENGINE=InnoDB AUTO_INCREMENT=102 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

