LOCK TABLES `refund_policies` WRITE;
/*!40000 ALTER TABLE `refund_policies` DISABLE KEYS */;
INSERT INTO `refund_policies` VALUES (22,'Shipping Policy','<p>Updated 14.01.2025</p><p><br></p><p><span style=\"background-color: transparent;\">Thank you for visiting and shopping at Waltzify. Below are the terms and conditions that constitute our Shipping Policy.</span></p><p><br></p><p><span style=\"background-color: transparent;\">1. Shipping Processing Time</span></p><p><span style=\"background-color: transparent;\">All orders are processed within 1-3 business days. Orders are not shipped or delivered on weekends or holidays.</span></p><p><span style=\"background-color: transparent;\">If we experience a high volume of orders, shipments may be delayed by a few days. Please allow additional days in transit for delivery. If there will be a significant delay in shipment of your order, we will contact you via email or phone.</span></p><p><br></p><p><span style=\"background-color: transparent;\">2. Shipping Rates &amp; Delivery Estimates</span></p><p><span style=\"background-color: transparent;\">Shipping charges for your order will be calculated and displayed at checkout based on your location and chosen shipping method.</span></p><p><span style=\"background-color: transparent;\">Standard Shipping: Estimated delivery time is 5-7 business days.</span></p><p><span style=\"background-color: transparent;\">Express Shipping: Estimated delivery time is 2-3 business days. charges may additional.</span></p><p><span style=\"background-color: transparent;\">Delivery delays can occasionally occur due to unforeseen circumstances.</span></p><p><br></p><p><span style=\"background-color: transparent;\">3. Shipment Confirmation &amp; Order Tracking</span></p><p><span style=\"background-color: transparent;\">You will receive a Shipment Confirmation Call/Msg/Whatsapp/Email once your order has shipped, containing your tracking number(s).</span></p><p><span style=\"background-color: transparent;\">The tracking number will be active within 24-48 hours.</span></p><p><br></p><p><span style=\"background-color: transparent;\">4. Customs, Duties, and Taxes</span></p><p><span style=\"background-color: transparent;\">Waltzify is not responsible for any customs and taxes applied to your order. All fees imposed during or after shipping are the responsibility of the customer (tariffs, taxes, etc.).</span></p><p><br></p><p><span style=\"background-color: transparent;\">5. Damages</span></p><p><span style=\"background-color: transparent;\">Waltzify is not liable for any products damaged or lost during shipping. If you received your order damaged, please contact the shipment carrier to file a claim.</span></p><p><span style=\"background-color: transparent;\">Save all packaging materials and damaged goods before filing a claim.</span></p><p><br></p><p><span style=\"background-color: transparent;\">6. Missing or Lost Packages</span></p><p><span style=\"background-color: transparent;\">If you haven’t received your package within the estimated delivery time, please reach out to our support team at 07314245858, 9522582422 info@waltzify.com for assistance.</span></p><p><br></p><p><span style=\"background-color: transparent;\">We will do our best to assist in tracking down the package, but once the package is with the carrier, responsibility lies with the shipping company.</span></p><p><br></p><p><span style=\"background-color: transparent;\">7. Contact Us</span></p><p><span style=\"background-color: transparent;\">For any questions regarding our shipping policy, please contact us info@waltzify.com</span></p><p><br></p><p><br></p>',1,'2026-01-14 10:15:19','2026-01-14 11:15:55'),(24,'Return & Refund Policy','<p>Updated 14.01.2025</p><p><br></p><p><span style=\"background-color: transparent;\">1. Return Period:</span></p><p><br></p><p><span style=\"background-color: transparent;\">You have 7 days from the date of delivery to request a return or exchange.</span></p><p><span style=\"background-color: transparent;\">Items must be unused, in their original packaging, and include all tags.</span></p><p><br></p><p><br></p><p><span style=\"background-color: transparent;\">2. Non-Returnable Items:&nbsp;</span></p><p><span style=\"background-color: transparent;\">We do not accept returns for:</span></p><ul><li><span style=\"background-color: transparent;\">Used item.</span></li><li><span style=\"background-color: transparent;\">Non manufacturing defect items.</span></li><li><span style=\"background-color: transparent;\">High sale items</span></li></ul><p><span style=\"background-color: transparent;\">Please note that all non-returnable items will be clearly marked as \"Non-Returnable\" on their respective product details pages.</span></p><p><br></p><p><span style=\"background-color: transparent;\">3. Refund Process:</span></p><p><br></p><p><span style=\"background-color: transparent;\">After we receive your returned item, we will inspect it and notify you of the approval status.</span></p><p><span style=\"background-color: transparent;\">If approved, a refund will be issued to your original payment method within 5-7 business days.</span></p><p><br></p><p><span style=\"background-color: transparent;\">4. Exchanges:</span></p><p>Defective or damaged items are eligible for free exchange, repair, or replacement of damaged parts. Customers must contact us within 7 days of receiving the item to request an exchange. Once the exchange request is approved, the<strong> </strong>replacement or damaged product will be delivered within 10–12 business days.</p><p><br></p><p><span style=\"background-color: transparent;\">5. Return Shipping Costs:</span></p><p><br></p><p><span style=\"background-color: transparent;\">Customer\'s Responsibility: Return shipping is the customer’s responsibility unless the return is due to our error.</span></p><p><span style=\"background-color: transparent;\">We can provide a prepaid return label, with the cost deducted from your refund.</span></p><p><br></p><p><span style=\"background-color: transparent;\">6. How to Request a Return:</span></p><p><span style=\"background-color: transparent;\">To start a return, reach out to our support team at </span><a href=\"mailto:info@waltzify.com\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"background-color: transparent; color: rgb(17, 85, 204);\">info@waltzify.com</a><span style=\"background-color: transparent;\">, 9522582422 with your order number and the reason for your return.</span></p>',1,'2026-01-14 11:16:56','2026-01-19 07:13:05');
/*!40000 ALTER TABLE `refund_policies` ENABLE KEYS */;
UNLOCK TABLES;

