INSERT INTO `reviews` VALUES (1,5,NULL,8,13,13,5,'Excellent service! The snake catcher arrived quickly and handled the situation very professionally. He was calm, knowledgeable, and ensured the snake was safely rescued and relocated without harm. Highly reliable and trustworthy service. Strongly recommended to anyone facing a snake emergency.',1,0,1,'APPROVED',NULL,'2026-01-07 10:42:02','2026-01-12 10:44:22'),(2,5,NULL,2,11,11,5,'Good everyday emergency eyewash bottle with easy-squeeze design; simple and portable.',1,0,1,'APPROVED',NULL,'2026-01-07 10:43:02','2026-02-28 11:16:29'),(4,2,NULL,1,7,7,2,'good',1,0,1,'APPROVED',NULL,'2026-01-07 10:45:25','2026-01-12 10:44:36'),(5,5,NULL,16,23,20,5,'Good quality breather, works smoothly and gives proper airflow. Satisfied with the product.',1,0,1,'APPROVED',NULL,'2026-01-12 08:28:43','2026-01-12 10:44:41'),(6,5,NULL,5,22,18,5,'High-quality wood coal with consistent burning and minimal smoke. Worth buying.',1,0,1,'APPROVED',NULL,'2026-01-12 08:29:25','2026-01-12 10:44:38'),(7,5,NULL,10,22,19,5,'Well-built milk can with good finishing. Maintains hygiene and is easy to clean.',1,0,1,'APPROVED',NULL,'2026-01-12 08:30:28','2026-01-12 10:44:40'),(9,7,NULL,5,31,28,5,'best product',1,0,0,'APPROVED',NULL,'2026-01-12 08:53:44','2026-01-12 08:53:44'),(10,7,NULL,9,30,27,5,'nice material ',1,0,1,'APPROVED',NULL,'2026-01-12 08:53:56','2026-03-02 07:27:03'),(11,7,NULL,18,29,26,5,'Strong  material ',1,0,1,'APPROVED',NULL,'2026-01-12 08:54:19','2026-03-02 07:27:06'),(12,7,NULL,11,28,25,5,'awsm.............................................',1,0,1,'APPROVED','2026-04-18 12:57:28','2026-01-12 08:54:38','2026-04-18 12:57:28'),(13,7,NULL,20,26,23,5,'usefully product...',1,0,1,'APPROVED',NULL,'2026-01-12 08:55:30','2026-03-02 07:27:08'),(17,18,NULL,433,52,52,3,'This product is Good ',1,0,0,'APPROVED',NULL,'2026-02-28 10:25:01','2026-02-28 10:25:01'),(18,NULL,6,433,NULL,NULL,2,'this product is awesome',1,1,0,'APPROVED',NULL,'2026-02-28 11:25:37','