INSERT INTO `terms_conditions` VALUES (1,'General Information','<p>Updated 14.01.2025</p><p><br></p><p>This website is operated by Waltzify and this website is owned by Mustafa Shah. Throughout the site, the terms “we”, “us”, and “our” refer to Waltzify.</p><p><span style=\"background-color: transparent;\">By visiting our site or purchasing something from us, you engage in our “Service” and agree to be bound by the following terms and conditions.</span></p>',1,'2026-01-07 10:06:15','2026-01-14 13:05:28'),(3,'Use of the Website','<p><span style=\"background-color: transparent;\">By using this website, you confirm that you are at least the age of majority in your state or province of residence, or that you have given us your consent to allow any of your minor dependents to use this site.</span></p><p><span style=\"background-color: transparent;\">You agree not to use our products for any illegal or unauthorized purpose and not to violate any laws in your jurisdiction.</span></p>',1,'2026-01-07 10:06:56','2026-01-07 10:06:56'),(5,'Product Information','<p><span style=\"background-color: transparent;\">We make every effort to display as accurately as possible the colors and images of our products. We cannot guarantee that your computer monitor’s display of any color will be accurate.</span></p><p><span style=\"background-color: transparent;\">Prices for our products are subject to change without notice. We reserve the right to modify or discontinue the Service or any part of it without notice.</span></p>',1,'2026-01-07 10:07:15','2026-01-07 10:07:15'),(7,'Orders & Payment','<p><span style=\"background-color: transparent;\">We reserve the right to refuse any order you place with us. If we cancel or make changes to your order, we will notify you by contacting the email or phone number provided at the time of order.</span></p><p><span style=\"background-color: transparent;\">Payment information must be accurate, complete, and current. You agree to provide up-to-date, valid payment information when making a purchase.</span></p>',1,'2026-01-07 10:08:11','2026-01-07 10:08:11'),(8,'Shipping & Delivery','<p><span style=\"background-color: transparent;\">Shipping times are estimates and are not guaranteed. Waltzify is not responsible for any delays caused by shipping carriers.</span></p><p><span style=\"background-color: transparent;\">Customers are responsible for providing accurate shipping addresses. We are not responsible for items delivered to incorrect addresses provided by the customer.</span></p>',1,'2026-01-07 10:08:25','2026-01-07 10:08:25'),(9,'Returns & Refunds','<p>Please refer to our Return &amp; Refund Policy <a href=\"https://waltzify.com/refund\" rel=\"noopener noreferrer\" target=\"_blank\"><strong><u>https://waltzify.com/refund</u></strong></a> for details on how to return items purchased from our site.</p><p>We accept return within 7 to 10 days from the date of delivery.</p><p>Replacement/damaged product will be delivered within 5-7 business days.</p>',1,'2026-01-07 10:09:29','2026-01-14 10:11:49'),(10,'Intellectual Property','<p>All content on this website, including text, graphics, logos, images, and software, is the property of Waltzify or our content suppliers and is protected by copyright and trademark laws.</p><p>You may not reproduce, distribute, or use any content without written permission from Waltzify.</p>',1,'2026-01-07 10:09:40','2026-01-07 10:10:22'),(12,'Limitation of Liability','<p>Waltzify will not be liable for any direct, indirect, incidental, or consequential damages arising from your use of our website or products, or for any other claim related in any way to your use of the Service.</p><p>Our</p><p>liability is limited to the maximum extent permitted by law.</p>',1,'2026-01-07 10:11:47','2026-01-07 10:11:47'),(13,'Governing Law','<p>These Terms &amp; Conditions and any separate agreements whereby we provide you Services shall be governed by and construed in accordance with the laws of INDIA.</p>',1,'2026-01-07 10:12:00','2026-01-07 10:12:00'),(14,'Changes to Terms & Conditions','<p>We reserve the right to update or change these terms at any time without notice. Your continued use of our website following any changes signifies your acceptance of those changes.</p>',1,'2026-01-07 10:12:12','2026-01-07 10:12:12'),(15,'Contact Information','<p>For any questions about these Terms &amp; Conditions, please contact us at:</p><p>Email: info@waltzify.com</p><p>Phone: 07314245858; 9522582422</p><p>Mailing Address: Waltzer India,Main Gate,</p><p>1A-Balaji Market, Hawa Bangala Rd, near R.R. Cat, opp. Hari Dham Mandir,</p><p>Indore, Madhya Pradesh 452009</p>',1,'2026-01-07 10:12:43','2026-01-07 10:12:43');
